"""Deterministic generated files with conflict detection for human edits."""

import hashlib
import html
import json
from pathlib import Path, PurePosixPath
import re

from .http import SyncError

SECRET = re.compile(r"(?:apify_api_[A-Za-z0-9]{32,}|gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{50,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----)")
MANIFEST = ".sync/manifest.json"


def json_text(value):
    return json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n"


def digest(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def inline(value):
    # Metadata belongs in a Markdown table, not executable HTML or Markdown links.
    value = " ".join(str(value).split())
    return html.escape(value).replace("|", "&#124;").replace("[", "&#91;").replace("]", "&#93;")


def render(brand, actors, previous=None):
    files, metadata = {}, []
    current_ids = {a["id"] for a in actors}
    for actor in actors:
        base = f"docs/actors/{actor['id']}"
        entry = {k: actor[k] for k in ("id", "name", "username", "title", "description", "categories", "status", "url", "build_id")}
        entry.update({"documentation": f"{base}/README.md", "input_schema": f"{base}/input-schema.json"})
        entry["readme_sha256"] = digest(actor["readme"])
        for key, filename in (("output_schema", "output-schema.json"), ("dataset_schema", "dataset-schema.json"), ("key_value_schema", "key-value-schema.json")):
            entry[key] = f"{base}/{filename}" if actor.get(key) is not None else None
            # Explicit null clears stale definitions rather than preserving old schema data.
            files[f"{base}/{filename}"] = json_text(actor.get(key))
        for key in ("input_schema", "output_schema", "dataset_schema", "key_value_schema"):
            entry[key + "_sha256"] = digest(json_text(actor.get(key)))
        metadata.append(entry)
        files[f"{base}/README.md"] = (
            f"> Published documentation from [{actor['username']}/{actor['name']}]({actor['url']}). "
            "This file is synchronized from the Actor's default published build. "
            "[Input schema](input-schema.json) · [Output schema](output-schema.json) · [Dataset schema](dataset-schema.json). Check Apify for current pricing and availability.\n\n"
            "<!-- Generated by apify-github-sync. Edit the README on Apify, not here. -->\n\n"
            + actor["readme"]
        )
        files[f"{base}/input-schema.json"] = json_text(actor["input_schema"])
    # Preserve reference pages for unlisted Actors without fetching private resources.
    # An unlisted status is not an assertion that an Actor was deleted or made private.
    for old in previous or []:
        if old["id"] not in current_ids:
            old = dict(old)
            old["status"] = "not-listed"
            base = f"docs/actors/{old['id']}"
            notice = "# Actor unavailable\n\nThis Actor is absent from the current complete public organization listing. Previously mirrored schemas have been cleared. Check the publisher's Apify organization for current availability.\n"
            files[f"{base}/README.md"] = notice
            old["readme_sha256"] = digest(notice)
            for key in ("input_schema", "output_schema", "dataset_schema", "key_value_schema"):
                files[f"{base}/{key.replace('_', '-')}.json"] = "null\n"
                old[key + "_sha256"] = digest("null\n")
            metadata.append(old)
    metadata.sort(key=lambda a: (a["title"].lower(), a["id"]))
    files["actors.json"] = json_text({"schema_version": 1, "brand": brand, "actors": metadata})
    rows = [f"# {brand} Actor catalog", "", "Published Actor reference material and links to runnable examples in [the project README](README.md).",
            "", "This catalog is maintained by the publisher. Pricing and execution are managed on Apify.", "",
            "| Actor | Purpose | Category | Reference |", "| --- | --- | --- | --- |"]
    for entry in metadata:
        if entry["status"] == "not-listed":
            continue
        title = inline(entry["title"]) + (" (deprecated)" if entry["status"] == "deprecated" else "")
        rows.append(f"| [{title}]({entry['url']}) | {inline(entry['description'])} | {inline(', '.join(entry['categories']))} | [Docs]({entry['documentation']}) |")
    absent = [a for a in metadata if a["status"] == "not-listed"]
    if absent:
        rows += ["", "## Previously listed Actors", "", "These Actors were absent from the latest complete public listing. Unavailable notices are retained at their stable paths, and previously mirrored schemas are cleared.", ""]
        rows += [f"- [{inline(a['title'])}]({a['documentation']})" for a in absent]
    files["CATALOG.md"] = "\n".join(rows) + "\n"
    return files


def checked_path(root, relative):
    path = PurePosixPath(relative)
    if path.is_absolute() or ".." in path.parts or "\\" in relative or ":" in relative:
        raise SyncError("Unsafe generated file path")
    destination = root.joinpath(*path.parts)
    for parent in [destination, *destination.parents]:
        if parent == root:
            break
        if parent.is_symlink():
            raise SyncError("Refusing to write through a symbolic link")
    return destination


def apply_files(root, files, repair=False, prune=False):
    root = Path(root).resolve()
    manifest_path = checked_path(root, MANIFEST)
    manifest = json.loads(manifest_path.read_text(encoding="utf-8")) if manifest_path.exists() else {"schema_version": 1, "files": {}}
    old_hashes = manifest.get("files")
    if manifest.get("schema_version") != 1 or not isinstance(old_hashes, dict):
        raise SyncError("Unsupported generated-file manifest")
    # Check every managed file before writing any bytes.
    for name, expected in old_hashes.items():
        file = checked_path(root, name)
        if not file.is_file() or digest(file.read_text(encoding="utf-8")) != expected:
            if repair and (name in files or (prune and name.startswith("site/"))):
                continue
            raise SyncError(f"Generated file was edited or deleted: {name}; restore it before syncing")
    new_hashes = dict(old_hashes)  # historical unlisted pages remain managed
    obsolete = [name for name in old_hashes if prune and name.startswith("site/") and name not in files]
    for name in obsolete:
        new_hashes.pop(name, None)
    for name, text in files.items():
        path = checked_path(root, name)
        if SECRET.search(text):
            raise SyncError(f"Credential-like text found in {name}; publication blocked")
        reserved = (name.startswith(("site/", ".automation/")) or name in (".github/workflows/documentation.yml", "LICENSE")
                    or re.fullmatch(r"docs/actors/[A-Za-z0-9]{8,40}/(?:README\.md|(?:input|output|dataset|key-value)-schema\.json)", name))
        if path.exists() and name not in old_hashes and path.read_text(encoding="utf-8") != text and not (repair and reserved):
            raise SyncError(f"Refusing to overwrite an unmanaged file: {name}")
        new_hashes[name] = digest(text)
    changed = []
    for name in obsolete:
        path = checked_path(root, name)
        if path.is_file():
            path.unlink()
            changed.append(name)
    all_files = dict(files)
    all_files[MANIFEST] = json_text({"schema_version": 1, "files": new_hashes})
    for name, text in all_files.items():
        path = checked_path(root, name)
        if not path.exists() or path.read_text(encoding="utf-8") != text:
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("w", encoding="utf-8", newline="\n") as stream:
                stream.write(text)
            changed.append(name)
    return changed


def example_status(root, actors):
    """Read JSON inputs only; never import or execute code from a target repo."""
    indexed = {a["id"]: a for a in actors}
    rows = ["# Example input checks", "", "Basic checks against the synchronized published input schemas. These are not live execution tests or full JSON Schema validation.",
            "", "| Example | Result |", "| --- | --- |"]
    for file in sorted((root / "examples").glob("*/example.json")):
        if file.is_symlink() or (file.parent / "input.json").is_symlink():
            raise SyncError("Example JSON inputs must not be symbolic links")
        try:
            definition = json.loads(file.read_text(encoding="utf-8"))
            payload = json.loads((file.parent / "input.json").read_text(encoding="utf-8"))
            actor = indexed.get(definition["actor_id"])
            if actor is None:
                message = "Actor is not in the current public snapshot; review availability"
            else:
                schema = actor["input_schema"]
                props = schema.get("properties", {})
                issues = ["missing " + k for k in (schema.get("required") or []) if k not in payload]
                for key, value in payload.items():
                    if key not in props:
                        issues.append("unknown field " + key)
                    elif "enum" in props[key] and value not in props[key]["enum"]:
                        issues.append("unsupported value for " + key)
                message = "; ".join(issues) if issues else "Required fields, field names, and enum values checked"
        except (ValueError, KeyError, TypeError, OSError, AttributeError):
            message = "Invalid example configuration or input; review manually"
        relative = file.parent.relative_to(root).as_posix()
        rows.append(f"| [{inline(file.parent.name)}]({relative}/README.md) | {inline(message)} |")
    return "\n".join(rows) + "\n"
